import{_ as s,H as i,f as a,i as t}from"./chunks/framework.BH2BK_3i.js";const E=JSON.parse('{"title":"04 | 快速上手（二）：LobeChat+AI网关+Ollama打造高可用大模型集群","description":"","frontmatter":{},"headers":[{"level":2,"title":"部署架构图","slug":"部署架构图","link":"#部署架构图","children":[]},{"level":2,"title":"使用 Ollama 启动 DS 模型","slug":"使用-ollama-启动-ds-模型","link":"#使用-ollama-启动-ds-模型","children":[]},{"level":2,"title":"网关选型","slug":"网关选型","link":"#网关选型","children":[{"level":3,"title":"AI 时代给网关带来的挑战","slug":"ai-时代给网关带来的挑战","link":"#ai-时代给网关带来的挑战","children":[]}]},{"level":2,"title":"AI 网关 Higress","slug":"ai-网关-higress","link":"#ai-网关-higress","children":[{"level":3,"title":"Higress 部署与测试","slug":"higress-部署与测试","link":"#higress-部署与测试","children":[]},{"level":3,"title":"API Key 二次分租","slug":"api-key-二次分租","link":"#api-key-二次分租","children":[]},{"level":3,"title":"Token 用量观测","slug":"token-用量观测","link":"#token-用量观测","children":[]}]},{"level":2,"title":"接入 LobeChat","slug":"接入-lobechat","link":"#接入-lobechat","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"DeepSeek应用开发实战/04｜快速上手（二）：LobeChat+AI网关+Ollama打造高可用大模型集群.md","filePath":"DeepSeek应用开发实战/04｜快速上手（二）：LobeChat+AI网关+Ollama打造高可用大模型集群.md","lastUpdated":1795486824000}'),n={name:"DeepSeek应用开发实战/04｜快速上手（二）：LobeChat+AI网关+Ollama打造高可用大模型集群.md"};function p(l,e,h,o,r,g){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="_04-快速上手-二-lobechat-ai网关-ollama打造高可用大模型集群" tabindex="-1">04 | 快速上手（二）：LobeChat+AI网关+Ollama打造高可用大模型集群 <a class="header-anchor" href="#_04-快速上手-二-lobechat-ai网关-ollama打造高可用大模型集群" aria-label="Permalink to &quot;04 | 快速上手（二）：LobeChat+AI网关+Ollama打造高可用大模型集群&quot;">​</a></h1><p>你好，我是邢云阳。</p><p>在上一节课，我们使用 Ollama 部署了一个 DeepSeek-R1:32B 的模型，并通过修改聊天模板，完成了让模型强制 think 的修改。今天这节课，我们继续上一节课的思路，完成多 Ollama实例的负载均衡的配置，使之成为一个高可用的 Ollama 集群。</p><p>话不多说，让我们先从集群架构设计开始吧。</p><h2 id="部署架构图" tabindex="-1">部署架构图 <a class="header-anchor" href="#部署架构图" aria-label="Permalink to &quot;部署架构图&quot;">​</a></h2><p>首先看一下整体的部署架构。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/1.png" alt=""></a></p><p>上节课，我介绍过，在我的服务器上，有两张 T4 卡，因此我会创建两个 Ollama 实例，两个实例分别占用一张卡，并且每一个实例都对应一个 DS-R1:32B 模型。</p><p>之后为了满足对于大模型服务的负载均衡和流量转发，我们需要针对 AI 时代的新需求去对API 网关进行选型。</p><p>最后为了能让用户像使用 ChatGPT 一样，通过一个前端页面与大模型进行问答交互，我部署了开源社区特别火的一款对话前端，名字叫 LobeChat。LobeChat 开箱即用，支持多模型的对接，非常适合我们做对话测试。</p><h2 id="使用-ollama-启动-ds-模型" tabindex="-1">使用 Ollama 启动 DS 模型 <a class="header-anchor" href="#使用-ollama-启动-ds-模型" aria-label="Permalink to &quot;使用 Ollama 启动 DS 模型&quot;">​</a></h2><p>接下来，我们启动一下两个 Ollama。我依然使用的是将模型下载服务器，然后挂载到 Docker容器内的启动方式。命令行如下所示，注意区分两个实例的名称以及端口号，不能重复。同时要注意 --gpus 参数的设置，第一个实例用 0 号卡，第二个实例用 1 号卡。</p><p>实例 1：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -dp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8880:11434</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --runtime=nvidia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --gpus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> device=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DeepSeek-R1-1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span></span></code></pre></div><p>实例 2：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -dp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8881:11434</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --runtime=nvidia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --gpus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> device=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DeepSeek-R1-2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span></span></code></pre></div><p>我们使用 docker ps 查看一下启动情况：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>root@aitest:~# docker ps</span></span>
<span class="line"><span>CONTAINER ID   IMAGE                                 COMMAND               CREATE</span></span>
<span class="line"><span>db280e09c715   docker.1ms.run/ollama/ollama:0.5.11   &quot;/bin/ollama serve&quot;   4 seco</span></span>
<span class="line"><span>30ea38431349   docker.1ms.run/ollama/ollama:0.5.11   &quot;/bin/ollama serve&quot;   17 sec</span></span></code></pre></div><p>可以看到两个实例都启动了。此时，你可以使用上节课的 curl 命令，来分别测试一下两个实例通过 API 方式的对话是否正常。</p><h2 id="网关选型" tabindex="-1">网关选型 <a class="header-anchor" href="#网关选型" aria-label="Permalink to &quot;网关选型&quot;">​</a></h2><p>根据我们的部署架构图，接下来就是 API 网关的选型了。在传统的业务中，我们经常使用Nginx 等作为流量转发和负载均衡网关。这对于单次 HTTP 连接时间短，单次请求数据量小的场景来说没有问题。但在 AI 时代，网关后端对接的不再是传统的 HTTP Server，而是大模型。</p><p>如果只是简单测试一下负载均衡效果，那使用 Nginx 完全 OK。但如果是真正的实现生产级别的应用，那么我们就需要针对 AI 时代的新挑战而使用 AI 网关，比如 Kong、Higress 等。</p><h3 id="ai-时代给网关带来的挑战" tabindex="-1">AI 时代给网关带来的挑战 <a class="header-anchor" href="#ai-时代给网关带来的挑战" aria-label="Permalink to &quot;AI 时代给网关带来的挑战&quot;">​</a></h3><p>AI 时代给网关带来了哪些新挑战呢？</p><p>第一，服务连续性。LLM 应用通常需要较长的内容生成时间，用户体验很大程度上依赖于对话的连续性。因此，如何在后端系统更新时保持服务不中断成为了一个关键问题。</p><p>第二，资源安全。与传统应用相比，LLM 服务处理单个请求时需要消耗大量计算资源。这种特性使得服务特别容易受到攻击，攻击者可以用很小的成本发起请求，却会给服务器带来巨大负担。如何保障后端系统的稳定性变得尤为重要。</p><p>第三，商业模式保护。很多 AGI 企业会提供免费调用额度来吸引用户，但这也带来了风险，部分黑灰产会利用这些免费额度封装成收费 API 牟利。如何防范这类商业损失是一个现实问题。</p><p>第四，内容安全。不同于传统 Web 应用的简单信息匹配，LLM 应用通过 AI 推理来生成内容。如何确保这些自动生成的内容安全合规，需要特别关注。</p><p>第五，多模型管理。当我们需要接入多个大模型时，如何统一管理不同厂商的 API，降低开发和维护成本也是一个重要课题。</p><p>在网关的流量层面，AI 时代还面临着三大新需求，分别是长连接、高延时和大带宽，我整理了一张表格描述每个需求的特点。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/2.png" alt=""></a></p><h2 id="ai-网关-higress" tabindex="-1">AI 网关 Higress <a class="header-anchor" href="#ai-网关-higress" aria-label="Permalink to &quot;AI 网关 Higress&quot;">​</a></h2><p>因此如果像做传统业务一样，仅仅考虑负载均衡，流量转发是远远不够的。考虑到这样的背景，我们的课程里将会使用阿里云开源 Higress，作为我们高可用大模型集群的网关。</p><h3 id="higress-部署与测试" tabindex="-1">Higress 部署与测试 <a class="header-anchor" href="#higress-部署与测试" aria-label="Permalink to &quot;Higress 部署与测试&quot;">​</a></h3><p>Higress 在 AI 时代之前是一个云原生 API 网关，在阿里内部，为解决 Tengine（加强版Nginx）reload 对长连接业务有损，以及 gRPC/Dubbo 负载均衡能力不足的问题，Higress 应运而生。Higress 提供了基于 K8s 的部署模式，以及基于 Docker 的 all-in-one 的部署模式，这节课，我们使用后一种模式。</p><p>首先执行如下命令，将安装脚本下载下来。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://higress.cn/ai-gateway/install.sh</span></span></code></pre></div><p>如果你只想内网使用，可以直接执行 bash install.sh 命令一键安装。但如果想将网关暴露在公网，则需要打开配置文件，在第 428 行找到如下图所示的内容，将红框中三行的 127.0.0.1:全部去掉。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/3.png" alt=""></a></p><p>然后执行 bash insta…sh 进行安装。首先会让你选择要对接什么大模型，此处可以不选，直接回车跳过。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/4.png" alt=""></a></p><p>之后出现如下显示，代表安装成功：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/5.png" alt=""></a></p><p>从安装信息中，我们可以看到 Higress 暴露了三个端口，分别是 HTTP 访问端口 8080，HTTPS 访问端口 8443，以及控制台访问端口 8001。</p><p>我们可以在浏览器输入 &lt; 公网 ip&gt;:8001 进入 Higress 控制台。首次进入会让用户初始化管理员账户。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/6.png" alt=""></a></p><p>Higress 针对 AI 的需求，设计了 AI 流量入口管理的功能，可以非常简单地完成添加大模型服务，以及添加大模型的访问路由等功能。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/7.png" alt=""></a></p><p>我们点击创建 AI 服务提供者，将服务器上的两个 Ollama 服务都添加上。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/8.png" alt=""></a></p><p>注意 Ollama 服务主机名要填服务器的公网地址，这是因为 Higress 运行在 Docker 容器中，访问不到服务器内网。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/9.png" alt=""></a></p><p>服务添加完成后，接下来就是添加访问路由了。由于我们是要对两个 Ollama 做负载均衡，因此需要在一台路由中，将两个 Ollama 服务都关联上。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/10.png" alt=""></a></p><p>Higress 同时支持设置每个服务的请求比例，在这里，我设置的是各占 50%。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/11.png" alt=""></a></p><p>设置完成后，便可以在服务器上使用 curl 命令进行测试了。Higress 提供了兼容 OpenAI 数据格式的服务，我们可以使用 OpenAI 数据格式进行路由的请求。命令如下：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/v1/chat/completions</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;model&quot;: &quot;deepseek-r1:32b&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;messages&quot;: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">     &quot;role&quot;: &quot;user&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">     &quot;content&quot;: &quot;你是一个python编程专家，请帮我写一个计算加法的程序&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   }</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&#39;</span></span></code></pre></div><p>此时 Higress 会将请求随机路由到一个 Ollama 服务上去，命令的输出如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/12.png" alt=""></a></p><p>可以看到，请求成功了。</p><h3 id="api-key-二次分租" tabindex="-1">API Key 二次分租 <a class="header-anchor" href="#api-key-二次分租" aria-label="Permalink to &quot;API Key 二次分租&quot;">​</a></h3><p>如果我们想将 Ollama 集群面向多用户提供服务，这种场景该如何满足呢？比如面向公司内部员工使用，每个员工一个 API Key，或者面向外部客户，按 API Key 使用量收费等。</p><p>Higress 提供了 API Key 二次分租的功能。我们可以这样理解这个功能—— Ollama 是房东，Higress 租下了 Ollama 的房子，然后又把房子租给了别人，自己变成了二房东。</p><p>接下来，我们进行测试。首先将页面切到消费者管理，创建消费者。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/13.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/14.png" alt=""></a></p><p>我们模拟向两个用户提供服务的场景，来创建两组认证令牌，也就是 API Key。</p><p>之后，用户如果使用 API Key 访问网关，则需要在请求头中进行添加，命令如下所示：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/v1/chat/completions</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer fcb8c143-bb01-4bf3-ad5c-6d76bc727e66&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;model&quot;: &quot;deepseek-r1:32b&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;messages&quot;: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">     &quot;role&quot;: &quot;user&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">     &quot;content&quot;: &quot;你是一个python编程专家，请帮我写一个计算加法的程序&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   }</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&#39;</span></span></code></pre></div><p>这样，Higress 就可以控制消费者的调用权限和调用额度，还可以配合可观测能力，对每个消费者的 token 用量进行观测统计。</p><h3 id="token-用量观测" tabindex="-1">Token 用量观测 <a class="header-anchor" href="#token-用量观测" aria-label="Permalink to &quot;Token 用量观测&quot;">​</a></h3><p>Higress 内置了 Prometheus + Grafana 的指标监控套件。可以将页面切换到 AI 控制面板进行查看。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/15.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/16.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/16.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/17.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/17.png" alt=""></a></p><h2 id="接入-lobechat" tabindex="-1">接入 LobeChat <a class="header-anchor" href="#接入-lobechat" aria-label="Permalink to &quot;接入 LobeChat&quot;">​</a></h2><p>curl 命令只是我们研发人员测试使用的，如果让用户也使用 curl，就太不像话了。因此最后，我们将网关接入到一个可视化的自然语言前端，为我们的整个方案画上圆满的句号。</p><p>在 GitHub 上，开源的自然语言前端有很多，热度比较高的有 OpenWebUI、LobeChat 等，今天我就用 LobeChat 为大家演示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/18.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/18.png" alt=""></a></p><p>LobeChat 的部署分为两种类型。第一种是新手体验版本的，这个版本只需要在本地部署一个对话客户端就可以使用，所有的历史对话数据，配置信息等都是存在 LobeChat 的云服务器上的。第二种则是完全私有化的部署，即数据存储在自己的本地。</p><p>由于这节课侧重演示方案，因此我就用新手版的，大家如果后续在生产使用，可以使用完全私有化版。</p><p>新手版 Lobechat 可以使用 docker 一键拉起：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ docker run -d -p 3210:3210 \\</span></span>
<span class="line"><span> -e OPENAI_API_KEY=fcb8c143-bb01-4bf3-ad5c-6d76bc727e66 \\</span></span>
<span class="line"><span> -e OPENAI_PROXY_URL=http://higress:8080/v1 \\</span></span>
<span class="line"><span> -e ACCESS_CODE=lobe66 \\</span></span>
<span class="line"><span> --name lobe-chat \\</span></span>
<span class="line"><span> lobehub/lobe-chat</span></span></code></pre></div><p>由于我们是通过 LobeChat 的 OpenAI 接口对接 Higress，因此需要填写 OPENAI_API_KEY和 OPENAI_PROXY_URL 两个参数，OPENAI_API_KEY 是上文中我们二次分租创建的 APIKey，如果你没有开启二次分租，则可以填写 unused。OPENAI_PROXY_URL 即为 higress的 HTTP 访问地址。LobeChat 的客户端会通过 3210 端口暴露。</p><p>在浏览器输入 &lt; 公网地址 &gt;:3210 即可打开 LobeChat 对话客户端，然后就可以开始对话了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/19.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/19.png" alt=""></a></p><p>大家测试后，会发现使用 LobeChat 进行对话，会像我们使用 DeepSeek 官网的对话页面一样，直接开始一个字一个字的输出，而不是等待一段时间后，直接把全部内容显示出来。这种一个字一个字的输出方式就叫流式模式，在内容特别多的大对话场景下，流式输出可以减轻服务器和网关的压力，还能让用户的使用体验更好。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>今天，我们在大家已经掌握 Ollama 的基本使用方法之后，又为大家引入了 AI 网关 Higress 以及对话前端 LobeChat。通过这两个组件，我们组成了一个带有可视化自然语言对话前端的高可用高可控的大模型集群。</p><p>这节课的重点在于网关的选型。传统的类似 Nginx 的网关已经无法应对 AI 时代的长连接、高延时和大带宽的要求。Hgress 是以 istio 和 envoy 为核心开发的，天然对于这些特性就有完美的契合。在加上其内置的多种插件，完全可以满足企业内外部大模型服务的提供。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>企业在提供大模型服务时，通常希望网关能够拦截一些用户提问中的敏感词，防止出现法律等方面的风险。我们可以使用 Higress 的哪个插件来实现这个功能呢？你以通过 Higress 是什么?-Higress 官网 里插件使用文档这部分来找到答案。</p><p>欢迎你在留言区展示你的思考结果，我们一起探讨。如果你觉得这节课的内容对你有帮助的话，也欢迎你分享给其他朋友，我们下节课再见！</p>`,94)])])}const c=s(n,[["render",p]]);export{E as __pageData,c as default};
